import 'dart:io';

import 'package:runfiles/runfiles.dart';

/// Reads a git-sourced pub spoke's `pubspec.yaml` from runfiles.
///
/// The spoke is generated by `pub.from_lock()` from a `source: git` lock entry,
/// so its runtime files reach a dependent test through the generated
/// `dart_library`'s `data`, like a hosted spoke's.
void main() {
  final runfiles = Runfiles.create();
  final path = runfiles.rlocation(
    'ai_rules_dart++pub+dart_pub__characters/pubspec.yaml',
  );
  final pubspec = File(path);
  if (!pubspec.existsSync()) {
    stderr.writeln('The git spoke pubspec.yaml is not in runfiles: $path');
    exit(1);
  }
  final content = pubspec.readAsStringSync();
  if (!content.contains('name: characters')) {
    stderr.writeln('Unexpected pubspec content at $path:\n$content');
    exit(1);
  }
}
